    echo "this commit rests on was made against ${BASE:0:7}'s reports"
    exit 1
fi
if git rev-parse -q --verify "refs/tags/$TAG" > /dev/null; then
    echo "the tag $TAG already exists"
    exit 1
fi
echo "ok  HEAD $(git log -1 --format='%h %s' HEAD); no tag $TAG yet"

say "the working tree holds these paths and reports/, and nothing else"
status="$(git -c core.fileMode=false status --porcelain --untracked-files=all)"
expected="$(printf '%s\n' "$PATHS" | sort)"
others="$(sed 's/^...//' <<< "$status" | grep -v '^reports/' | sort || true)"
if [ "$others" != "$expected" ]; then
    echo "outside reports/, the tree is not what this script expects:"
    diff <(echo "$expected") <(echo "$others") || true
    exit 1
fi
want_reports="$(awk 'NF == 2 {print $2}' <<< "$REPORT_SHAS" | sort)"
got_reports="$(grep -E '^.. reports/' <<< "$status" | sed 's/^...//' | sort || true)"
if [ "$got_reports" != "$want_reports" ]; then
    echo "reports/ does not move in exactly the reports this commit reviewed:"
    diff <(echo "$want_reports") <(echo "$got_reports") || true
    exit 1
fi
# Captured first: a grep -q at the end of a pipe can close it early, and under
# pipefail the writer's SIGPIPE would read as no match.
unregenerated="$(grep -E '^.. reports/' <<< "$status" | grep -vE '^ M ' || true)"
if [ -n "$unregenerated" ]; then
    echo "a report is added, deleted or untracked; the freeze only regenerates:"
    echo "$unregenerated"
    exit 1
fi
if [ "$(grep -c '^?? ' <<< "$status")" != "1" ] \
    || ! grep -qx '?? scripts/commit_freeze.sh' <<< "$status"; then
    echo "the one untracked path should be this script"
    exit 1
fi
echo "ok  $(wc -l <<< "$expected") paths and $(wc -l <<< "$want_reports") reports"

say "1/10  the README and every moved report are the reviewed ones, byte for byte"
if [ "$(sha256sum README.md | cut -d' ' -f1)" != "$README_SHA" ]; then
