import ast
import sys
from pathlib import Path

# The module docstring's item 12, the comment above BAGGING_SEEDS, the
# constant, and the comment above SUBMISSION_KEY, each in the same lines.
ALLOWED = {*range(69, 74), *range(337, 375), 382, *range(933, 939)}
NAMES = ("BOOSTER_PARAMS", "SEED_AVERAGE_ADOPTED")

old = Path(sys.argv[1]).read_text(encoding="utf-8")
new = Path("src/taxiout/models.py").read_text(encoding="utf-8")
a, b = old.splitlines(), new.splitlines()
if len(a) != len(b):
    raise SystemExit(f"models.py changed length, {len(a)} to {len(b)} lines")
moved = {i + 1 for i, (x, y) in enumerate(zip(a, b)) if x != y}
if not moved or moved - ALLOWED:
    raise SystemExit(f"models.py moved outside its four places: {sorted(moved - ALLOWED)}")


def read(text):
    found = {}
    for node in ast.parse(text).body:
        if isinstance(node, ast.AnnAssign) and getattr(node.target, "id", "") in NAMES:
            found[node.target.id] = ast.literal_eval(node.value)
    return found


was, now = read(old), read(new)
if was["BOOSTER_PARAMS"] != now["BOOSTER_PARAMS"]:
    raise SystemExit("BOOSTER_PARAMS moved")
if (was["SEED_AVERAGE_ADOPTED"], now["SEED_AVERAGE_ADOPTED"]) != (False, True):
    raise SystemExit("SEED_AVERAGE_ADOPTED is not the parent's False made True")
cell = {k: now["BOOSTER_PARAMS"][k] for k in
        ("n_estimators", "learning_rate", "num_leaves", "min_child_samples")}
print(f"  ok  {len(moved)} lines moved, all in the four places;"
      f" BOOSTER_PARAMS unchanged, {cell}; SEED_AVERAGE_ADOPTED True")
PY

