import sys
from pathlib import Path

sys.path.insert(0, "src")
from taxiout.osm import pin_agreement, read_sidecar
from taxiout.provenance import OSM_PINS

pins = {p.icao: p.timestamp_osm_base for p in OSM_PINS}
got = pin_agreement(Path("data/raw"), pins)
bad = [f"{c.icao} {c.branch}: {c.problem}" for c in got if c.problem]
if bad or len(got) != len(pins) or any(c.branch != "rebuilt" for c in got):
    raise SystemExit(f"the pin check does not read eleven clean rebuilt entries: {bad or got}")
stamps = sorted({e["timestamp_osm_base"] for e in read_sidecar(Path("data/raw")).values()})
print(f"  ok  {len(got)} rebuilt entries, none with a problem; stamps {stamps[0]} to {stamps[-1]}")
PY

say "6/10  every report that reads the cache verifies by its parsed elements"
"$PY" - <<'PY'
import sys
from pathlib import Path

sys.path.insert(0, "src")
from taxiout.provenance import elements_digest, is_overpass_answer, parse_report_inputs

READERS = (
    "reports/geometry_gaps.md",
    "reports/penalty_sensitivity.md",
    "reports/runway_crosscheck.md",
    "reports/stand_coverage.md",
    "reports/taxi_routing.md",
)
for report in READERS:
    rows = [r for r in parse_report_inputs(Path(report).read_text(encoding="utf-8"))
            if is_overpass_answer(r.path)]
    if len(rows) != 11 or not all(r.by_elements for r in rows):
        raise SystemExit(f"{report}: {len(rows)} cached answers, not eleven by their elements")
    stale = [r.path for r in rows if elements_digest(r.path) != r.digest]
    if stale:
        raise SystemExit(f"{report}: stale by elements: {stale}")
    print(f"  ok  {report}: 11 cached answers, each verified by its parsed elements")
PY

