import sys

sys.path.insert(0, "scripts")
sys.path.insert(0, "src")
import check_provenance as cp
from taxiout.provenance import PROVENANCE_PENDING, REPORT_INPUTS_DECLARED, REPORTS_WITHOUT_FOOTER

if PROVENANCE_PENDING:
    raise SystemExit(f"{len(PROVENANCE_PENDING)} item(s) still pending")
if REPORTS_WITHOUT_FOOTER:
    raise SystemExit("REPORTS_WITHOUT_FOOTER is not empty")
declared = {r for _g, r in REPORT_INPUTS_DECLARED}
frozen = {f.path for f in cp.FROZEN_DOCUMENTS}
silent = set(cp.report_writers()) - declared - frozen
if silent or len(declared) != 15:
    raise SystemExit(f"{len(declared)} reports declare their inputs; silent: {sorted(silent)}")
print(f"  ok  pending empty; all {len(declared)} live reports declare their inputs")
